with ProductsBySupplier as (select supplier_id, max(price) as max_price, count(distinct price) as unique_brands from products where price > 510 group by supplier_id) select suppliers.id, suppliers.country, suppliers.city, ProductsBySupplier.max_price, ProductsBySupplier.unique_brands from suppliers inner join ProductsBySupplier on suppliers.id = ProductsBySupplier.supplier_id order by city desc, unique_brands desc
